function selectElement(element){const root=liveRoot();if(!root||!element||!root.contains(element))return;const custom=element.closest('[data-panel-studio-element]');if(custom&&root.contains(custom))element=custom;const selector=selectorFor(element,root),kind=element===root?'root':element.dataset.panelStudioElement?'custom':'builtin',id=kind==='root'?'root':element.dataset.panelStudioElement||nodeId(selector);selectLayer(kind,id,selector,nameFor(element),typeFor(element));}
