  const frameDoc=frameDocument(),element=liveSelected();if(!frameDoc)return;const overlay=installFrameOverlay(frameDoc);if(!overlay)return;if(!element||!element.isConnected){overlay.style.display='none';return;}const rect=element.getBoundingClientRect();overlay.style.display='block';overlay.style.left=`${rect.left}px`;overlay.style.top=`${rect.top}px`;overlay.style.width=`${Math.max(1,rect.width)}px`;overlay.style.height=`${Math.max(1,rect.height)}px`;overlay.toggleAttribute('data-locked',!!selectedNode(false)?.locked);
