function viewportSize(){return doc.ui.viewport==='mobile'?[390,844]:doc.ui.viewport==='tablet'?[768,900]:[1440,900];}
function centerCanvas(){const canvas=$('#pseCanvas',content);if(!canvas)return;canvas.scrollLeft=Math.max(0,(canvas.scrollWidth-canvas.clientWidth)/2);canvas.scrollTop=Math.max(0,(canvas.scrollHeight-canvas.clientHeight)/2);}
function applyViewport(){const frame=$('#pseLiveFrame',content),surface=$('#pseFrameSurface',content),viewport=$('#pseFrameViewport',content);if(!frame||!surface||!viewport)return;const [width,height]=viewportSize(),scale=doc.ui.zoom/100;frame.style.width=`${width}px`;frame.style.height=`${height}px`;frame.style.transform=`scale(${scale})`;surface.style.width=`${width*scale}px`;surface.style.height=`${height*scale}px`;viewport.dataset.viewport=doc.ui.viewport;const label=$('#pseZoomLabel',content);if(label)label.textContent=`${Math.round(doc.ui.zoom)}%`;const status=$('#pseStatusZoom',content);if(status)status.textContent=`${Math.round(doc.ui.zoom)}%`;$$('.pse-viewport',content).forEach(button=>button.classList.toggle('active',button.dataset.viewport===doc.ui.viewport));setTimeout(centerCanvas,40);}
