  const node=M.createElement(type,parentSelector);node.parentId=parentId;let id=node.id,n=2;const used=new Set(p.customElements.map(item=>item.id));while(used.has(id))id=`${node.id}-${n++}`;node.id=id;p.customElements.push(node);checkpoint(before);doc=M.normalize(doc);queueSave();syncFrame();setTimeout(()=>{selectLayer('custom',id,`[data-panel-studio-element="${CSS.escape(id)}"]`,node.name,type);scanLayers();},90);notify(`${node.name} adicionado ao painel.`);
